def transform(g, dbg=False):
    h,w=len(g),len(g[0])
    out=[row[:] for row in g]
    seen=set()
    for i in range(h):
        for j in range(w):
            if g[i][j]==0 and (i,j) not in seen:
                comp=[(i,j)]; seen.add((i,j)); st=[(i,j)]
                while st:
                    y,x=st.pop()
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and g[ny][nx]==0 and (ny,nx) not in seen:
                            seen.add((ny,nx)); comp.append((ny,nx)); st.append((ny,nx))
                seeds=[(y,x) for y,x in comp if g[y][x]!=0]
                if dbg: print('comp at',i,j,'size',len(comp),'seeds',seeds)
                if not seeds: continue
                r0=min(y for y,x in seeds); c0=min(x for y,x in seeds)
                r1=max(y for y,x in seeds); c1=max(x for y,x in seeds)
                ph,pw=r1-r0+1,c1-c0+1
                pat=[[g[r0+a][c0+b] for b in range(pw)] for a in range(ph)]
                if dbg: print('pat',pat,'region rows',min(y for y,x in comp),max(y for y,x in comp),'cols',min(x for y,x in comp),max(x for y,x in comp))
                for y,x in comp:
                    out[y][x]=pat[(y-r0)%ph][(x-c0)%pw]
    return out
